<script setup>import{onMounted,ref}from'vue';import{api}from'../../api/http.js';import PageHeader from'../../components/common/PageHeader.vue';import T from'../../components/common/WorkspaceTable.vue';const requests=ref([]),transactions=ref([]),error=ref('');const money=n=>new Intl.NumberFormat('en-US',{style:'currency',currency:'USD'}).format(n||0);async function load(){try{const d=await api.get('/workspace/finance',{per_page:100});requests.value=d.requests.data;transactions.value=d.transactions}catch(x){error.value=x.message}}async function decide(id,decision){try{await api.post(`/workspace/finance/${id}/review`,{decision});await load()}catch(x){error.value=x.message}}onMounted(load)</script><template><PageHeader title="Finance" description="Review requests and track cash movement."/><p v-if="error" class="form-error">{{error}}</p><h2>Finance requests</h2><T :columns="[{key:'full_name',label:'Employee'},{key:'request_type',label:'Type'},{key:'amount',label:'Amount'},{key:'description',label:'Description'},{key:'status',label:'Status'}]" :rows="requests"><template #cell-amount="{row}">{{money(row.amount)}}</template><template #actions="{row}"><button v-if="row.status==='Pending'" @click="decide(row.id,'Approved')">Approve</button><button v-if="row.status==='Pending'" @click="decide(row.id,'Rejected')">Reject</button><button v-if="row.status==='Approved'" @click="decide(row.id,'Paid')">Pay</button></template></T><h2 class="section-title">Recent transactions</h2><T :columns="[{key:'created_at',label:'Date'},{key:'transaction_type',label:'Type'},{key:'description',label:'Description'},{key:'direction',label:'Direction'},{key:'amount',label:'Amount'}]" :rows="transactions"><template #cell-amount="{row}">{{money(row.amount)}}</template></T></template>